-- READ-ONLY exact-key and nearest 300-second target check for legacy rows in existing gap windows.
SELECT o.gap_id, COUNT(*) AS old_source_rows, SUM(w.`dateTime` IS NOT NULL) AS exact_wh1080_matches, SUM(z.`dateTime` IS NOT NULL) AS exact_eu_old_matches, SUM(r.`dateTime` IS NOT NULL) AS exact_reconstruction_matches, SUM(MOD(o.`dateTime`,300)=0) AS on_300s_grid, SUM(MOD(o.`dateTime`,300)<>0) AS off_300s_grid, COUNT(DISTINCT (o.`dateTime`-MOD(o.`dateTime`,300)+IF(MOD(o.`dateTime`,300)>=150,300,0))) AS distinct_nearest_300s_slots, COUNT(*)-COUNT(DISTINCT (o.`dateTime`-MOD(o.`dateTime`,300)+IF(MOD(o.`dateTime`,300)>=150,300,0))) AS source_projection_collisions, SUM(rp.`dateTime` IS NOT NULL) AS rows_projecting_to_occupied_reconstruction_slots, SUM(NOT (o.`outTemp` <=> w.`outTemp`)) AS outTemp_old_wh_conflicts, SUM(NOT (o.`outTemp` <=> z.`outTemp`)) AS outTemp_old_euold_conflicts, SUM(NOT (o.`outHumidity` <=> w.`outHumidity`)) AS outHumidity_old_wh_conflicts, SUM(NOT (o.`outHumidity` <=> z.`outHumidity`)) AS outHumidity_old_euold_conflicts, SUM(NOT (o.`rain` <=> w.`rain`)) AS rain_old_wh_conflicts, SUM(NOT (o.`rain` <=> z.`rain`)) AS rain_old_euold_conflicts, SUM(NOT (o.`rainRate` <=> w.`rainRate`)) AS rainRate_old_wh_conflicts, SUM(NOT (o.`rainRate` <=> z.`rainRate`)) AS rainRate_old_euold_conflicts, SUM(NOT (o.`windSpeed` <=> w.`windSpeed`)) AS windSpeed_old_wh_conflicts, SUM(NOT (o.`windSpeed` <=> z.`windSpeed`)) AS windSpeed_old_euold_conflicts, SUM(NOT (o.`windGust` <=> w.`windGust`)) AS windGust_old_wh_conflicts, SUM(NOT (o.`windGust` <=> z.`windGust`)) AS windGust_old_euold_conflicts, SUM(NOT (o.`windDir` <=> w.`windDir`)) AS windDir_old_wh_conflicts, SUM(NOT (o.`windDir` <=> z.`windDir`)) AS windDir_old_euold_conflicts, SUM(NOT (o.`barometer` <=> w.`barometer`)) AS barometer_old_wh_conflicts, SUM(NOT (o.`barometer` <=> z.`barometer`)) AS barometer_old_euold_conflicts, SUM(NOT (o.`pressure` <=> w.`pressure`)) AS pressure_old_wh_conflicts, SUM(NOT (o.`pressure` <=> z.`pressure`)) AS pressure_old_euold_conflicts, SUM(NOT (o.`altimeter` <=> w.`altimeter`)) AS altimeter_old_wh_conflicts, SUM(NOT (o.`altimeter` <=> z.`altimeter`)) AS altimeter_old_euold_conflicts, SUM(o.`usUnits`<>w.`usUnits`) AS usUnits_old_wh_conflicts, SUM(o.`interval`<>w.`interval`) AS interval_old_wh_conflicts, SUM(o.`usUnits`<>z.`usUnits`) AS usUnits_old_euold_conflicts, SUM(o.`interval`<>z.`interval`) AS interval_old_euold_conflicts FROM (SELECT CASE WHEN `dateTime`>1357466400 AND `dateTime`<1357472100 THEN 1 WHEN `dateTime`>1359457200 AND `dateTime`<1359529500 THEN 2 WHEN `dateTime`>1360676100 AND `dateTime`<1360680300 THEN 3 WHEN `dateTime`>1360921500 AND `dateTime`<1360927200 THEN 4 WHEN `dateTime`>1362166800 AND `dateTime`<1362171600 THEN 5 WHEN `dateTime`>1362580800 AND `dateTime`<1362644700 THEN 6 WHEN `dateTime`>1363401300 AND `dateTime`<1363407300 THEN 7 WHEN `dateTime`>1363409100 AND `dateTime`<1363413300 THEN 8 WHEN `dateTime`>1363415100 AND `dateTime`<1363419300 THEN 9 WHEN `dateTime`>1363421100 AND `dateTime`<1363425300 THEN 10 WHEN `dateTime`>1363427100 AND `dateTime`<1363431300 THEN 11 WHEN `dateTime`>1363431300 AND `dateTime`<1363435500 THEN 12 WHEN `dateTime`>1364238300 AND `dateTime`<1364242200 THEN 13 WHEN `dateTime`>1364694900 AND `dateTime`<1364698800 THEN 14 WHEN `dateTime`>1367210100 AND `dateTime`<1367228400 THEN 15 WHEN `dateTime`>1367228400 AND `dateTime`<1367251800 THEN 16 WHEN `dateTime`>1369740600 AND `dateTime`<1369760100 THEN 17 WHEN `dateTime`>1371064200 AND `dateTime`<1371070200 THEN 18 WHEN `dateTime`>1371070200 AND `dateTime`<1371094500 THEN 19 WHEN `dateTime`>1372629000 AND `dateTime`<1372635000 THEN 20 WHEN `dateTime`>1373500500 AND `dateTime`<1373544300 THEN 21 WHEN `dateTime`>1382829900 AND `dateTime`<1382856600 THEN 22 WHEN `dateTime`>1386043500 AND `dateTime`<1386078300 THEN 23 WHEN `dateTime`>1388063700 AND `dateTime`<1388088000 THEN 24 ELSE NULL END AS gap_id, `dateTime`, `outTemp`, `outHumidity`, `rain`, `rainRate`, `windSpeed`, `windGust`, `windDir`, `barometer`, `pressure`, `altimeter`, `usUnits`, `interval` FROM `old_weewx`.`archive` WHERE (`dateTime`>1357466400 AND `dateTime`<1357472100) OR (`dateTime`>1359457200 AND `dateTime`<1359529500) OR (`dateTime`>1360676100 AND `dateTime`<1360680300) OR (`dateTime`>1360921500 AND `dateTime`<1360927200) OR (`dateTime`>1362166800 AND `dateTime`<1362171600) OR (`dateTime`>1362580800 AND `dateTime`<1362644700) OR (`dateTime`>1363401300 AND `dateTime`<1363407300) OR (`dateTime`>1363409100 AND `dateTime`<1363413300) OR (`dateTime`>1363415100 AND `dateTime`<1363419300) OR (`dateTime`>1363421100 AND `dateTime`<1363425300) OR (`dateTime`>1363427100 AND `dateTime`<1363431300) OR (`dateTime`>1363431300 AND `dateTime`<1363435500) OR (`dateTime`>1364238300 AND `dateTime`<1364242200) OR (`dateTime`>1364694900 AND `dateTime`<1364698800) OR (`dateTime`>1367210100 AND `dateTime`<1367228400) OR (`dateTime`>1367228400 AND `dateTime`<1367251800) OR (`dateTime`>1369740600 AND `dateTime`<1369760100) OR (`dateTime`>1371064200 AND `dateTime`<1371070200) OR (`dateTime`>1371070200 AND `dateTime`<1371094500) OR (`dateTime`>1372629000 AND `dateTime`<1372635000) OR (`dateTime`>1373500500 AND `dateTime`<1373544300) OR (`dateTime`>1382829900 AND `dateTime`<1382856600) OR (`dateTime`>1386043500 AND `dateTime`<1386078300) OR (`dateTime`>1388063700 AND `dateTime`<1388088000)) o LEFT JOIN `weewx_WH1080`.`archive` w ON w.`dateTime`=o.`dateTime` LEFT JOIN `pocasi-loucka.eu_old`.`archive` z ON z.`dateTime`=o.`dateTime` LEFT JOIN `loucka_reconstruction`.`archive` r ON r.`dateTime`=o.`dateTime` LEFT JOIN `loucka_reconstruction`.`archive` rp ON rp.`dateTime`=(o.`dateTime`-MOD(o.`dateTime`,300)+IF(MOD(o.`dateTime`,300)>=150,300,0)) WHERE o.gap_id IS NOT NULL GROUP BY o.gap_id ORDER BY o.gap_id;
